import csv, json, urllib.request, urllib.error, urllib.parse, datetime, sys
NC = "http://localhost:8080"
TABLE = "m58xsjo6at01ohl"
CSV = "/root/unitex-finrep/normalized/deals_all.csv"
LOG = "/root/nocodb-deals-sync.log"
TOK = open("/root/nocodb-token.txt").read().strip()
def req(method, path, data=None):
    h = {"Content-Type": "application/json", "xc-token": TOK}
    r = urllib.request.Request(NC + path, data=json.dumps(data).encode() if data is not None else None, headers=h, method=method)
    try:
        with urllib.request.urlopen(r, timeout=60) as resp:
            b = resp.read().decode()
            return resp.status, (json.loads(b) if b else {})
    except urllib.error.HTTPError as e:
        return e.code, {"err": e.read().decode()[:200]}
    except Exception as e:
        return 0, {"err": str(e)[:200]}
def norm(n):
    s = str(n or "").strip()
    try: return str(int(s))
    except Exception: return s
